from math import gcd

def main():
    n, m = map(int, sys.stdin.read().split())
    if m < n - 1:
        print("Impossible")
        return
    print("Possible")
    edges = []
    for i in range(1, n):
        edges.append((i, i + 1))
    additional_edges = m - (n - 1)
    current_edge = 1
    while additional_edges > 0:
        for i in range(1, n + 1):
            for j in range(i + 1, n + 1):
                if gcd(i, j) == 1 and (i, j) not in edges and (j, i) not in edges:
                    edges.append((i, j))
                    additional_edges -= 1
                    if additional_edges == 0:
